"""UploadHandler: buffers the partner batch payload from the request body.

`handle_upload(request)` is the POST /uploads entry point. The WSGI dispatcher (app/wsgi.py) calls this
handler with a STABLE signature: handle_upload(request). The request body holds the partner's batch.
"""


class UploadHandler:
    def handle_upload(self, request):
        if request.method != "POST":
            return {"status": 405, "body": {"error": "method not allowed"}}
        body = request.body
        if isinstance(body, str):
            body = body.encode("utf-8")
        # No size limit: the full body is buffered whole into memory however large it is (the LMT-3301
        # problem: an oversized body is an OOM/DoS vector). Wiring a max-body-size check is the follow-up.
        n = len(body)
        return {"status": 200, "body": {"accepted_bytes": n, "status": "buffered"}}

